from lib10 import *
M='maths'
def B(ch,cn,t,tn,*a,**k): build(M,ch,t,tn,*a,cname=cn,tname=tn,**k)
# ---------------- Ch1 Real Numbers
C,CN='real-numbers','Real Numbers'
B(C,CN,'fundamental-theorem-of-arithmetic','Fundamental Theorem of Arithmetic, HCF and LCM',
 "Breaking a number into building blocks",
 "A shopkeeper packs 12 pencils in a box. Can he pack the same pencils in fours or sixes? Numbers break into smaller blocks just like boxes. Today we see that every number breaks into prime blocks in exactly one way.",
 [("Chapter 1 of the textbook revisits positive integers. A prime number has exactly two factors, 1 and itself, and a composite number has more than two factors.","prime and composite"),
  ("The Fundamental Theorem of Arithmetic says: every composite number can be written as a product of primes, and this factorisation is unique, apart from the order of the primes.","unique factorisation"),
  ("For example, 32760 = 2 x 2 x 2 x 3 x 3 x 5 x 7 x 13, which we write as 2 cubed x 3 squared x 5 x 7 x 13.","32760 = 2^3 x 3^2 x 5 x 7 x 13"),
  ("The theorem also says a number like 4 to the power n can never end in the digit 0, because its only prime factor is 2 and a number ending in 0 needs the prime 5 as well.","4^n never ends in 0"),
  ("To find the HCF by prime factorisation, take each common prime with the smallest power. To find the LCM, take every prime that appears with the greatest power.","HCF = smallest power"),
  ("Take 6 = 2 x 3 and 20 = 2 squared x 5. The HCF is 2 and the LCM is 2 squared x 3 x 5 = 60.","HCF 2, LCM 60"),
  ("For any two positive integers a and b, HCF(a, b) x LCM(a, b) = a x b. Check: 2 x 60 = 120 = 6 x 20.","HCF x LCM = a x b"),
  ("Remember that this product rule is for two numbers only. For three numbers the textbook gives a different relation in the note to the reader.","two numbers only")],
 ("Find the LCM and HCF of 12, 15 and 21 using prime factorisation.",[("12 = 2^2 x 3, 15 = 3 x 5, 21 = 3 x 7.","Write each number as a product of primes."),("HCF takes common primes with the smallest power: only 3 is common, so HCF = 3.","Common to all three: 3."),("LCM takes every prime with the greatest power: 2^2 x 3 x 5 x 7 = 420.","Include 2, 3, 5 and 7 each once with the biggest power seen.")]),
 ("How do you find HCF and LCM from prime factors?",["Write each number as a product of primes","HCF uses common primes with smallest power","LCM uses all primes with greatest power"],["Using HCF x LCM = product for three numbers"]),
 ["Every composite number is a unique product of primes (apart from order).","HCF = product of common primes with the smallest powers; LCM = product of all primes with the greatest powers.","For two positive integers, HCF x LCM = product of the two numbers.","A number of the form 4^n cannot end in 0."],
 [mcq("r1-fta1",1,"The prime factorisation of 140 is","2^2 x 5 x 7",[("2 x 5 x 14","14 is not a prime."),("2^3 x 5 x 7","2^3 x 5 x 7 = 280.")],"140 = 4 x 35 = 2^2 x 5 x 7."),
  tf("r1-fta2",1,"Prime factorisation of a composite number is unique apart from the order of primes.",True,"This is the Fundamental Theorem of Arithmetic."),
  num("r2-fta3",2,"HCF of 26 and 91 is",13,"26 = 2 x 13 and 91 = 7 x 13, so HCF = 13.",[(1,"They share the prime 13.")]),
  num("r2-fta4",2,"If HCF(12, 18) = 6, find LCM(12, 18).",36,"LCM = (12 x 18) / 6 = 36.",[(216,"216 is the product, not the LCM.")]),
  mcq("r2-fta5",2,"Assertion (A): 6^n can never end in digit 0 for any natural number n. Reason (R): 6^n = 2^n x 3^n has no prime factor 5. Choose the correct option.","Both A and R are true and R explains A",[("Both are true but R does not explain A","R is exactly why A holds: a number ending in 0 needs the prime 5."),("A is true but R is false","R is true.")],"A number ending in 0 is divisible by 10, so it needs both 2 and 5. 6^n has no 5."),
  short("r3-fta6",3,"Write the LCM of 6 and 20.",["60"],"6 = 2 x 3, 20 = 2^2 x 5, LCM = 2^2 x 3 x 5 = 60.",[("120","120 is a common multiple but not the least.")]),
  mcq("r3-fta7",3,"Two bells ring every 12 and 18 minutes. After how many minutes do they ring together again?","36",[("6","6 is the HCF."),("216","216 is the product, not the LCM.")],"LCM of 12 and 18 is 36."),
  tf("r3-fta8",3,"The HCF of two numbers is always a factor of their LCM.",True,"HCF divides both numbers and so divides their LCM.")])
B(C,CN,'irrational-numbers','Irrational numbers and proofs',
 "The number that never ends",
 "Measure the diagonal of a one-unit square and you get a length that no fraction can describe exactly. Today we prove that such numbers really exist.",
 [("A rational number can be written as p by q where p and q are integers and q is not zero. An irrational number cannot be written like this.","rational and irrational"),
  ("The textbook first proves a helping result: if a prime p divides a squared, then p divides a.","p divides a^2 => p divides a"),
  ("To prove that root 2 is irrational we use contradiction. Suppose root 2 = a by b, where a and b have no common factor other than 1.","proof by contradiction"),
  ("Squaring gives 2 b squared = a squared, so 2 divides a squared and therefore 2 divides a. Write a = 2c.","2b^2 = a^2"),
  ("Then 2 b squared = 4 c squared, so b squared = 2 c squared and 2 divides b as well. Now 2 divides both a and b, which contradicts our assumption that they have no common factor.","contradiction"),
  ("So our assumption was wrong, and root 2 is irrational. The same method proves that root 3 and root 5 are irrational.","root 2 is irrational"),
  ("The sum or difference of a rational and an irrational number is irrational. The product or quotient of a non-zero rational and an irrational number is irrational.","rational + irrational"),
  ("Be careful: the sum of two irrationals can be rational. For example root 2 and minus root 2 add up to 0.","two irrationals")],
 ("Prove that 3 + 2 root 5 is irrational.",[("Suppose 3 + 2 root 5 is rational, equal to a by b with b not zero.","Start by assuming the opposite."),("Then root 5 = (a - 3b) / 2b, and the right side is rational.","Rearrange to isolate root 5."),("But root 5 is irrational, a contradiction. So 3 + 2 root 5 is irrational.","The assumption fails.")]),
 ("Explain in steps why root 2 is irrational.",["Assume root 2 = a/b in lowest terms","Show 2 divides both a and b","This contradicts lowest terms"],["Thinking a decimal that looks long is automatically irrational"]),
 ["A number is irrational if it cannot be written as p/q with integers p and q (q not zero).","If a prime p divides a^2 then p divides a.","Root 2, root 3 and root 5 are irrational, proved by contradiction.","Rational + irrational and non-zero rational x irrational are irrational."],
 [mcq("r1-irr1",1,"Which of these is irrational?","root 7",[("root 49","root 49 = 7, which is rational."),("0.25","0.25 = 1/4 is rational.")],"7 is not a perfect square, so root 7 is irrational."),
  tf("r1-irr2",1,"The sum of two irrational numbers is always irrational.",False,"Root 2 + (minus root 2) = 0, which is rational."),
  mcq("r2-irr3",2,"Which of these is rational?","(2 + root 3)(2 - root 3)",[("2 + root 3","A rational plus an irrational is irrational."),("3 root 2","A non-zero rational times an irrational is irrational.")],"(2 + root 3)(2 - root 3) = 4 - 3 = 1."),
  mcq("r2-irr4",2,"Assertion (A): 5 - root 3 is irrational. Reason (R): The difference of a rational and an irrational number is irrational.","Both A and R are true and R explains A",[("A is true but R is false","R is a standard result and is true."),("A is false but R is true","A follows from R, so A is true.")],"5 is rational and root 3 is irrational, so their difference is irrational."),
  short("r2-irr5",2,"Is 0.1010010001... (non-terminating, non-repeating) rational or irrational? Write one word.",["irrational"],"A decimal that neither terminates nor repeats is irrational.",[("rational","Rational decimals terminate or repeat.")]),
  tf("r3-irr6",3,"A rational number has a terminating or a repeating decimal expansion.",True,"This is how rational numbers look in decimal form."),
  mcq("r3-irr7",3,"In the proof that root 2 is irrational, the contradiction arises because","a and b both turn out divisible by 2",[("a is odd","We never assume a is odd."),("b is zero","b cannot be zero in a fraction.")],"We began with a and b having no common factor but ended with 2 dividing both."),
  num("r3-irr8",3,"Decimal expansion of 7/8 terminates after how many decimal places? (7/8 = 0.875)",3,"0.875 has three decimal digits.",[(2,"Count the digits 8, 7, 5.")])])
# ---------------- Ch2 Polynomials
C,CN='polynomials','Polynomials'
B(C,CN,'zeroes-and-graphs','Zeroes of a polynomial and their graphs',
 "The curve that meets the road",
 "A ball thrown upward follows a curve. The points where the curve touches the ground tell us when the ball is at height zero. Those points are the zeroes of a polynomial.",
 [("A polynomial of degree 1 is linear, of degree 2 is quadratic and of degree 3 is cubic. A quadratic looks like a x squared + b x + c with a not zero.","degree"),
  ("A zero of a polynomial p of x is a number k such that p of k equals 0.","p(k) = 0"),
  ("Geometrically, the zeroes of p of x are the x-coordinates of the points where the graph of y = p of x meets the x-axis.","x-axis"),
  ("The graph of a linear polynomial is a straight line and it cuts the x-axis at exactly one point, so it has one zero.","line: 1 zero"),
  ("The graph of a quadratic polynomial is a parabola. It opens upward if a is positive and downward if a is negative.","parabola"),
  ("A parabola can cut the x-axis at two points, touch it at one point, or not meet it at all. So a quadratic has at most 2 zeroes.","at most 2 zeroes"),
  ("A cubic polynomial has at most 3 zeroes because its graph can cross the x-axis at most three times.","cubic: at most 3"),
  ("For example, x squared - 3x - 4 = (x - 4)(x + 1), so its zeroes are 4 and minus 1 and the parabola cuts the x-axis there.","x^2 - 3x - 4")],
 ("Find the zeroes of x squared - 2x - 8.",[("Factorise: x^2 - 2x - 8 = (x - 4)(x + 2).","Find two numbers with product -8 and sum -2: -4 and +2."),("Put each factor equal to zero: x = 4 or x = -2.","A product is zero when a factor is zero."),("So the parabola cuts the x-axis at (4, 0) and (-2, 0).","Zeroes are x-coordinates.")]),
 ("What do the zeroes of a polynomial mean on its graph?",["Zeroes are x-coordinates","Where the graph meets the x-axis","A quadratic has at most two"],["Reading y-coordinates as zeroes"]),
 ["A zero of p(x) is a number k with p(k) = 0.","Zeroes are the x-coordinates of the points where y = p(x) cuts the x-axis.","A quadratic has at most 2 zeroes, a cubic at most 3.","The graph of a quadratic is a parabola."],
 [mcq("r1-zg1",1,"The zeroes of x^2 - 1 are","1 and -1",[("1 only","(-1)^2 - 1 = 0 as well."),("0 and 1","0^2 - 1 = -1, not 0.")],"x^2 - 1 = (x - 1)(x + 1)."),
  tf("r1-zg2",1,"A quadratic polynomial can have at most two zeroes.",True,"Its graph (a parabola) cuts the x-axis at most twice."),
  num("r2-zg3",2,"If the graph of y = p(x) cuts the x-axis at 3 points, p(x) has how many zeroes?",3,"Each intersection point gives one zero.",[(2,"Count the intersection points.")]),
  mcq("r2-zg4",2,"The graph of y = x^2 + 1 does not cut the x-axis. So it has","no real zeroes",[("one zero","One zero means the parabola touches the axis."),("two zeroes","Two zeroes mean two intersection points.")],"x^2 + 1 is always at least 1, so it is never 0."),
  short("r2-zg5",2,"Find the zero of 2x + 5. Write it as a decimal.",["-2.5","-5/2"],"2x + 5 = 0 gives x = -5/2 = -2.5.",[("2.5","Check the sign: 2(2.5) + 5 = 10, not 0.")]),
  mcq("r3-zg6",3,"Case study: A parabola opens upward and its lowest point is above the x-axis. How many zeroes does the polynomial have?","0",[("1","One zero needs the vertex on the axis."),("2","Two zeroes need the parabola to cross the axis twice.")],"The curve never reaches y = 0."),
  tf("r3-zg7",3,"The graph of a linear polynomial a x + b (a not zero) cuts the x-axis at exactly one point.",True,"The zero is -b/a."),
  num("r3-zg8",3,"How many zeroes can a cubic polynomial have at most?",3,"A cubic graph can cross the x-axis at most 3 times.",[(2,"That is for a quadratic.")])])
B(C,CN,'zeroes-and-coefficients','Relationship between zeroes and coefficients',
 "Sum and product - a shortcut",
 "If you know the two roots of a quadratic, can you build the quadratic? There is a neat link between roots and coefficients that saves a lot of work.",
 [("Let alpha and beta be the zeroes of the quadratic polynomial a x squared + b x + c.","alpha and beta"),
  ("Then the sum of the zeroes is alpha + beta = minus b by a.","sum = -b/a"),
  ("And the product of the zeroes is alpha x beta = c by a.","product = c/a"),
  ("Check with x squared - 3x - 4: the zeroes are 4 and -1. Their sum is 3 = -(-3)/1 and their product is -4 = -4/1.","check"),
  ("To form a quadratic from its zeroes, use x squared - (sum) x + (product), because any multiple of it has the same zeroes.","x^2 - (sum)x + product"),
  ("For a cubic a x cubed + b x squared + c x + d with zeroes alpha, beta and gamma, the sum is minus b by a.","cubic sum = -b/a"),
  ("The sum of products taken two at a time is c by a, and the product of all three zeroes is minus d by a.","alpha beta gamma = -d/a"),
  ("Remember the signs: the sum has a minus, the product of two has no sign change, and the product of three has a minus.","watch the signs")],
 ("Find a quadratic polynomial whose zeroes have sum 6 and product 5, and then find the zeroes.",[("Quadratic = x^2 - (sum)x + product = x^2 - 6x + 5.","Use the formula."),("Factorise: x^2 - 6x + 5 = (x - 1)(x - 5).","Numbers with product 5 and sum -6."),("The zeroes are 1 and 5, and indeed 1 + 5 = 6 and 1 x 5 = 5.","Check against the sum and product.")]),
 ("How are zeroes of a quadratic connected to its coefficients?",["Sum = -b/a","Product = c/a","Quadratic = x^2 - (sum)x + product"],["Forgetting the negative sign in -b/a"]),
 ["For a x^2 + b x + c: sum of zeroes = -b/a, product = c/a.","A quadratic with given zeroes: x^2 - (sum)x + (product), up to a constant multiple.","For a cubic: sum = -b/a, sum of pair products = c/a, product = -d/a."],
 [mcq("r1-zc1",1,"The sum of the zeroes of x^2 - 5x + 6 is","5",[("-5","The sum is -b/a = 5."),("6","6 is the product.")],"-b/a = -(-5)/1 = 5."),
  num("r1-zc2",1,"Product of the zeroes of 2x^2 + 7x + 3",1.5,"c/a = 3/2 = 1.5.",[(3,"Divide by a = 2.")]),
  mcq("r2-zc3",2,"A quadratic with zeroes 2 and 3 is","x^2 - 5x + 6",[("x^2 + 5x + 6","The sum is 5, so the middle term is -5x."),("x^2 - 6x + 5","That has zeroes 1 and 5.")],"Sum 5, product 6."),
  mcq("r2-zc4",2,"Assertion (A): If the sum of zeroes of a quadratic is 0, the polynomial has no x term. Reason (R): Sum of zeroes = -b/a.","Both A and R are true and R explains A",[("A is true, R is false","R is true."),("A is false, R is true","If -b/a = 0 then b = 0, so there is no x term.")],"Sum 0 means b = 0."),
  short("r2-zc5",2,"If one zero of x^2 - 7x + 12 is 3, the other is",["4"],"Sum = 7, so the other = 7 - 3 = 4.",[("9","Product 12 / 3 = 4.")]),
  num("r3-zc6",3,"Sum of the zeroes of the cubic x^3 - 6x^2 + 11x - 6",6,"-b/a = -(-6)/1 = 6.",[(-6,"Careful with the sign.")]),
  tf("r3-zc7",3,"The product of all three zeroes of a x^3 + b x^2 + c x + d is -d/a.",True,"This is the cubic relationship."),
  mcq("r3-zc8",3,"If alpha and beta are zeroes of x^2 - 4x + 3, then alpha + beta + alpha beta =","7",[("1","Sum 4 + product 3 = 7."),("12","That is 4 x 3.")],"4 + 3 = 7.")])
# ---------------- Ch3 Pair of linear equations
C,CN='pair-of-linear-equations-in-two-variables','Pair of Linear Equations in Two Variables'
B(C,CN,'graphical-method','Graphical method and nature of solutions',
 "Two roads, one meeting point",
 "Two friends start walking along two straight roads. Will the roads cross, run side by side, or be the same road? That is exactly what a pair of linear equations tells us.",
 [("A pair of linear equations in two variables looks like a1 x + b1 y + c1 = 0 and a2 x + b2 y + c2 = 0.","a1x + b1y + c1 = 0"),
  ("Each equation is a straight line on the graph. Solving the pair means finding where the two lines meet.","two lines"),
  ("If the lines intersect at one point, there is a unique solution and the pair is consistent.","intersecting: unique solution"),
  ("If the lines coincide, there are infinitely many solutions and the pair is dependent and consistent.","coincident: infinitely many"),
  ("If the lines are parallel, there is no solution and the pair is inconsistent.","parallel: no solution"),
  ("We can decide the case without drawing. If a1 by a2 is not equal to b1 by b2, the lines intersect.","a1/a2 not b1/b2"),
  ("If a1 by a2 = b1 by b2 not equal to c1 by c2, the lines are parallel. If all three ratios are equal, the lines coincide.","a1/a2 = b1/b2 = c1/c2"),
  ("For x + y = 5 and 2x + 2y = 10 the ratios are all 1 by 2, so the lines coincide.","coincident example")],
 ("Does the pair x + 2y = 4 and 2x + 4y = 12 have a solution?",[("Compare ratios: a1/a2 = 1/2, b1/b2 = 2/4 = 1/2, c1/c2 = 4/12 = 1/3.","Write the three ratios."),("The first two ratios are equal but the third is different.","a1/a2 = b1/b2 not c1/c2."),("So the lines are parallel and the pair is inconsistent - no solution.","Parallel lines never meet.")]),
 ("How do you tell the nature of solutions from the coefficients?",["Compare a1/a2, b1/b2, c1/c2","Unequal first two: one solution","All equal: infinitely many; third different: none"],["Comparing a1/b1 instead of a1/a2"]),
 ["A pair of linear equations is shown by two lines.","Intersecting lines: unique solution (consistent); coincident lines: infinitely many (dependent); parallel lines: none (inconsistent).","Use the ratios a1/a2, b1/b2, c1/c2 to decide."],
 [mcq("r1-gm1",1,"The pair x + y = 4 and x - y = 2 has","one solution",[("no solution","The lines are not parallel."),("infinitely many solutions","The lines are different and not coincident.")],"1/1 is not equal to 1/(-1), so the lines intersect: x = 3, y = 1."),
  tf("r1-gm2",1,"Parallel lines represent an inconsistent pair of equations.",True,"They never meet, so there is no common solution."),
  mcq("r2-gm3",2,"For which value of k does 2x + 3y = 5 and 4x + ky = 10 have infinitely many solutions?","6",[("3","2/4 = 3/3 is false."),("5","Equal ratios need k = 6.")],"2/4 = 3/k = 5/10 gives k = 6."),
  mcq("r2-gm4",2,"Assertion (A): x + 2y = 3 and 2x + 4y = 7 have no solution. Reason (R): The lines are parallel.","Both A and R are true and R explains A",[("A true, R false","The ratios 1/2 = 2/4 not 3/7 show the lines are parallel."),("A false, R true","No solution follows from the lines being parallel.")],"Parallel lines have no common point."),
  num("r2-gm5",2,"Solve graphically: x + y = 6, x - y = 2. Find x.",4,"Adding gives 2x = 8, x = 4 (and y = 2).",[(2,"2 is y.")]),
  mcq("r3-gm6",3,"Case study: Two taxis charge fixed 20 plus 5 per km and fixed 30 plus 5 per km. Their lines are","parallel",[("intersecting","Different fixed charges but the same rate give parallel lines."),("coincident","The fixed charges differ.")],"Same slope, different intercept."),
  tf("r3-gm7",3,"If a1/a2 is not equal to b1/b2, the pair has a unique solution.",True,"The lines have different slopes, so they cross once."),
  num("r3-gm8",3,"How many solutions does 3x + 2y = 6, 6x + 4y = 12 have? Write 0, 1 or 99 for infinitely many.",99,"All ratios are 1/2 so the lines coincide.",[(1,"They are the same line."),(0,"They coincide, not parallel.")])])
B(C,CN,'algebraic-methods','Substitution and elimination methods',
 "Solving without a graph",
 "Drawing graphs takes time and accuracy. Two algebraic tricks, substitution and elimination, give exact answers in a few lines.",
 [("In the substitution method, express one variable in terms of the other from one equation, then substitute into the second.","substitution"),
  ("Take s - t = 3 and s/3 + t/2 = 6. From the first, s = t + 3.","s = t + 3"),
  ("Substitute: (t + 3)/3 + t/2 = 6. Multiply by 6: 2t + 6 + 3t = 36, so 5t = 30 and t = 6, giving s = 9.","t = 6, s = 9"),
  ("In the elimination method we make the coefficients of one variable equal by multiplying, then add or subtract the equations to remove it.","elimination"),
  ("Solve 2x + 3y = 8 and 4x + 6y = 7. Multiply the first by 2: 4x + 6y = 16, which is inconsistent with 4x + 6y = 7.","inconsistent check"),
  ("Always check the final answer by putting it back in both equations.","verify"),
  ("Many word problems reduce to a pair of linear equations: ages, money, speed in still water and against a stream, and digits of a number.","word problems"),
  ("Some equations that are not linear can be turned linear by substituting, for example u = 1 by x and v = 1 by y.","u = 1/x")],
 ("The sum of two numbers is 27 and their difference is 5. Find them.",[("Let the numbers be x and y: x + y = 27 and x - y = 5.","Form two equations."),("Add: 2x = 32, so x = 16.","Elimination removes y."),("Then y = 27 - 16 = 11. Check: 16 - 11 = 5.","Substitute and verify.")]),
 ("When will you use elimination instead of substitution?",["When coefficients can be matched easily","Add or subtract to remove a variable","Check the answer in both equations"],["Forgetting to change both sides while multiplying"]),
 ["Substitution: express one variable and substitute.","Elimination: equalise a coefficient, then add or subtract.","Word problems are turned into two linear equations; always verify.","Equations in 1/x and 1/y can be reduced to linear form."],
 [mcq("r1-al1",1,"The solution of x + y = 10, x - y = 4 is","(7, 3)",[("(3, 7)","x is bigger than y here."),("(6, 4)","6 - 4 = 2, not 4.")],"Adding: 2x = 14, x = 7, y = 3."),
  num("r1-al2",1,"Solve 3x = 12 - y with x = 2. Find y.",6,"3(2) = 12 - y gives y = 6.",[(4,"6 = 12 - y.")]),
  num("r2-al3",2,"Father's age is three times his son's. In 12 years he will be twice as old. Son's present age?",12,"3s + 12 = 2(s + 12) gives s = 12.",[(36,"36 is the father's age.")]),
  mcq("r2-al4",2,"The pair 2x + y = 7 and x - y = 2 has solution","(3, 1)",[("(2, 3)","2 - 3 = -1, not 2."),("(1, 5)","1 - 5 = -4.")],"Adding gives 3x = 9."),
  mcq("r2-al5",2,"Assertion (A): Elimination can solve 5x + 2y = 12 and 3x - 2y = 4. Reason (R): Adding the equations removes y.","Both A and R are true and R explains A",[("A true, R false","Adding gives 8x = 16, y disappears."),("A false, R true","The method works, so A is true.")],"8x = 16, so x = 2 and y = 1."),
  short("r3-al6",3,"Solve x + y = 14, x - y = 4. Write x.",["9"],"2x = 18 gives x = 9.",[("5","5 is y.")]),
  tf("r3-al7",3,"After solving a pair of equations you should verify the answer in both equations.",True,"This catches arithmetic slips."),
  num("r3-al8",3,"A numerator n is 1 less than the denominator 6. Find n.",5,"n = 6 - 1 = 5.",[(7,"Subtract, not add.")])])
# ---------------- Ch4 Quadratic equations
C,CN='quadratic-equations','Quadratic Equations'
B(C,CN,'factorisation-method','Quadratic equations and factorisation',
 "Splitting the middle term",
 "A rectangular plot has area 528 square metres and its length is one more than twice its breadth. Finding the breadth leads to a quadratic equation.",
 [("A quadratic equation in x has the standard form a x squared + b x + c = 0 where a is not zero.","ax^2 + bx + c = 0"),
  ("A number alpha is a root if a alpha squared + b alpha + c equals 0. The roots of the equation are the zeroes of the polynomial.","root = zero"),
  ("To factorise, split the middle term. For 2x squared - 5x + 3 we need two numbers with product 6 and sum -5. They are -2 and -3.","split the middle term"),
  ("Write 2x squared - 2x - 3x + 3 = 2x(x - 1) - 3(x - 1) = (2x - 3)(x - 1).","(2x - 3)(x - 1)"),
  ("Set each factor to zero: x = 3/2 or x = 1. These are the two roots.","x = 3/2, 1"),
  ("Before solving a word problem, write the situation as an equation in standard form, then factorise.","form the equation"),
  ("Always reject a root that does not make sense, such as a negative length or a fractional number of people.","reject impossible roots"),
  ("Check each root by substituting it into the original equation.","verify")],
 ("The product of two consecutive positive integers is 306. Find the integers.",[("Let them be x and x + 1: x(x + 1) = 306 so x^2 + x - 306 = 0.","Form the equation."),("Factorise: (x + 18)(x - 17) = 0, so x = -18 or 17.","Numbers with product -306 and sum 1: 18 and -17."),("Positive integers: 17 and 18. Check: 17 x 18 = 306.","Reject -18.")]),
 ("How do you solve a quadratic by factorisation?",["Write in standard form","Split the middle term","Equate each factor to zero"],["Forgetting to reject impossible roots"]),
 ["Standard form: a x^2 + b x + c = 0 with a not zero.","Roots can be found by splitting the middle term and equating each factor to zero.","Reject roots that do not fit the situation."],
 [mcq("r1-fm1",1,"Which is a quadratic equation?","x^2 - 3x + 2 = 0",[("x - 3 = 0","This is linear."),("x^3 - x = 0","This is cubic.")],"The highest power is 2."),
  num("r1-fm2",1,"One root of x^2 - 5x + 6 = 0 is 2. The other is",3,"Sum of roots is 5.",[(6,"6 is the product.")]),
  mcq("r2-fm3",2,"Roots of x^2 - 7x + 12 = 0","3 and 4",[("2 and 6","2 + 6 = 8."),("-3 and -4","Sum would be -7.")],"(x - 3)(x - 4) = 0."),
  mcq("r2-fm4",2,"Assertion (A): x(x + 1) = 0 has roots 0 and -1. Reason (R): A product is zero if one factor is zero.","Both A and R are true and R explains A",[("A true, R false","R is the zero product property."),("A false, R true","The roots are 0 and -1.")],"x = 0 or x + 1 = 0."),
  num("r2-fm5",2,"A rectangle has length 3 more than breadth and area 40. Breadth?",5,"b(b + 3) = 40 gives (b + 8)(b - 5) = 0; b = 5.",[(8,"8 is the length.")]),
  short("r3-fm6",3,"Positive root of x^2 - 9 = 0",["3"],"x = 3 or -3; positive is 3.",[("9","x squared is 9, not x.")]),
  tf("r3-fm7",3,"Every quadratic equation has exactly two real roots.",False,"x^2 + 1 = 0 has no real roots."),
  mcq("r3-fm8",3,"Case study: A ball's height satisfies h = 0 when t^2 - 4t = 0. The ball is on the ground at t =","0 and 4 seconds",[("only 4","t = 0 also works."),("2 seconds","2 gives -4.")],"t(t - 4) = 0.")])
B(C,CN,'quadratic-formula-nature-of-roots','Quadratic formula and nature of roots',
 "When factorising fails",
 "Not every quadratic splits neatly into factors. The quadratic formula always works and the discriminant tells us in advance what kind of roots to expect.",
 [("Complete the square on a x squared + b x + c = 0 and we get the quadratic formula.","quadratic formula"),
  ("The roots are x = (-b plus or minus the square root of b squared - 4ac) divided by 2a.","x = (-b ± √D)/2a"),
  ("The expression b squared - 4ac is called the discriminant. We write it as D.","D = b^2 - 4ac"),
  ("If D is greater than 0, the equation has two distinct real roots.","D > 0"),
  ("If D equals 0, the two roots are equal and real, each equal to -b by 2a.","D = 0"),
  ("If D is less than 0, there are no real roots, because the square root of a negative number is not real.","D < 0"),
  ("For 2x squared - 7x + 3 = 0, D = 49 - 24 = 25. So x = (7 plus or minus 5)/4, giving 3 and 1/2.","2x^2 - 7x + 3"),
  ("For x squared + 4x + 5, D = 16 - 20 = -4, which is negative, so there are no real roots.","D = -4")],
 ("Find k for which kx(x - 2) + 6 = 0 has two equal roots.",[("Write kx^2 - 2kx + 6 = 0, so a = k, b = -2k, c = 6.","Standard form."),("D = 4k^2 - 24k = 4k(k - 6) = 0 gives k = 0 or 6.","Equal roots need D = 0."),("k = 0 makes it non-quadratic, so k = 6.","Reject k = 0.")]),
 ("What does the discriminant tell us?",["D > 0 two distinct roots","D = 0 equal roots","D < 0 no real roots"],["Forgetting -b/2a for equal roots"]),
 ["Quadratic formula: x = (-b ± √(b^2 - 4ac))/2a.","D > 0: two distinct real roots; D = 0: equal roots; D < 0: no real roots.","Use D to decide nature of roots without solving."],
 [mcq("r1-qf1",1,"Discriminant of x^2 - 4x + 4","0",[("8","16 - 16 = 0."),("-8","b squared - 4ac = 0 here.")],"b^2 - 4ac = 16 - 16."),
  tf("r1-qf2",1,"If D < 0 a quadratic equation has no real roots.",True,"The square root of D is not real."),
  mcq("r2-qf3",2,"x^2 + x + 1 = 0 has","no real roots",[("two real roots","D = 1 - 4 = -3."),("equal roots","D is not 0.")],"D = -3."),
  num("r2-qf4",2,"Value of D for 3x^2 - 5x + 2 = 0",1,"25 - 24 = 1.",[(49,"Recompute: 4ac = 24.")]),
  mcq("r2-qf5",2,"Assertion (A): 2x^2 - 6x + 9/2 = 0 has equal roots. Reason (R): Its discriminant is zero.","Both A and R are true and R explains A",[("A true, R false","D = 36 - 36 = 0."),("A false, R true","D = 0 means equal roots, so A is true.")],"D = 36 - 4(2)(9/2) = 0."),
  num("r3-qf6",3,"If x^2 + kx + 4 = 0 has equal roots and k > 0, k =",4,"D = k^2 - 16 = 0.",[(2,"Check k^2 = 16.")]),
  short("r3-qf7",3,"Roots of x^2 - 2x - 3 = 0 (write the positive one)",["3"],"(x - 3)(x + 1) = 0.",[("1","1 is not a root.")]),
  tf("r3-qf8",3,"The zeroes of a quadratic polynomial and the roots of the corresponding equation are the same.",True,"They are solutions of the same condition p(x) = 0.")])
# ---------------- Ch5 Arithmetic progressions
C,CN='arithmetic-progressions','Arithmetic Progressions'
B(C,CN,'nth-term-of-an-ap','Arithmetic progressions and the nth term',
 "Stairs with equal steps",
 "A taxi charges 15 for the first km and 8 for each extra km. The fares 15, 23, 31, 39 grow by the same amount each time. Such lists are arithmetic progressions.",
 [("An arithmetic progression, or AP, is a list of numbers in which each term is obtained by adding a fixed number d to the previous term.","AP"),
  ("The fixed number d is called the common difference. It can be positive, negative or zero.","common difference d"),
  ("If the first term is a, the AP is a, a + d, a + 2d, a + 3d and so on.","a, a+d, a+2d"),
  ("To test whether a list is an AP, check that a2 - a1, a3 - a2, a4 - a3 all give the same value.","check differences"),
  ("The nth term of an AP is a sub n = a + (n - 1) d.","an = a + (n-1)d"),
  ("For the AP 3, 8, 13, 18, the first term is 3 and d = 5, so the 10th term is 3 + 9 x 5 = 48.","a = 3, d = 5"),
  ("To find which term equals 78, solve 3 + (n - 1) 5 = 78, so n - 1 = 15 and n = 16.","which term?"),
  ("If a term is a fraction or a negative number there is no problem, but n must always be a positive integer.","n positive integer")],
 ("Which term of the AP 21, 18, 15, ... is -81?",[("a = 21, d = -3. Use a_n = a + (n - 1)d = -81.","Identify a and d."),("21 - 3(n - 1) = -81 so 3(n - 1) = 102 and n - 1 = 34.","Solve for n."),("n = 35, so -81 is the 35th term.","n is a whole number, so it is a term.")]),
 ("What are the key facts about an AP?",["Fixed difference d","an = a + (n-1)d","n must be a positive integer"],["Mixing up a_n with n"]),
 ["An AP has a constant common difference d.","a_n = a + (n - 1)d.","If the n found is not a positive integer, the number is not a term."],
 [mcq("r1-ap1",1,"The common difference of 2, 5, 8, 11 is","3",[("2","2 is the first term."),("-3","The terms increase.")],"5 - 2 = 3."),
  tf("r1-ap2",1,"1, 4, 9, 16 is an AP.",False,"Differences are 3, 5, 7."),
  num("r2-ap3",2,"10th term of 2, 7, 12, ...",47,"2 + 9 x 5 = 47.",[(52,"That is the 11th term.")]),
  mcq("r2-ap4",2,"Which is the AP?","7, 11, 15, 19",[("1, 2, 4, 8","Ratios are equal, not differences."),("3, 6, 8, 13","Differences are unequal.")],"d = 4."),
  mcq("r2-ap5",2,"Assertion (A): 2, 4, 8 is not an AP. Reason (R): 4 - 2 is not equal to 8 - 4.","Both A and R are true and R explains A",[("A true, R false","R is true: 2 and 4."),("A false, R true","They are not an AP.")],"Differences 2 and 4 differ."),
  num("r3-ap6",3,"30th term of the AP 100, 97, 94, ...",13,"100 + 29 x (-3) = 13.",[(187,"d is negative.")]),
  short("r3-ap7",3,"Find d if a_1 = 5 and a_4 = 14",["3"],"a + 3d = 14 so 3d = 9.",[("9","d is 3.")]),
  tf("r3-ap8",3,"The nth term of an AP is a + nd.",False,"It is a + (n - 1)d.")])
B(C,CN,'sum-of-n-terms','Sum of the first n terms of an AP',
 "Gauss and the quick sum",
 "A story says a boy was asked to add 1 to 100 and answered at once. He paired 1 with 100, 2 with 99 and so on. That idea gives us the sum formula for every AP.",
 [("Pair the first and last terms: each pair has the same sum, so we get n by 2 pairs of the sum a + l.","pairing"),
  ("The sum of the first n terms of an AP is S = n by 2 times (2a + (n - 1) d).","S = n/2 [2a + (n-1)d]"),
  ("If the last term l is known, the sum is S = n by 2 times (a + l).","S = n/2 (a + l)"),
  ("Add 1 to 100: n = 100, a = 1, l = 100, so S = 50 x 101 = 5050.","1 + ... + 100 = 5050"),
  ("Find the sum of the first 22 terms of 8, 3, -2: a = 8, d = -5, S = 11 (16 - 105) = -979.","a = 8, d = -5"),
  ("The nth term can be found from sums: a_n = S_n - S_(n-1).","an = Sn - S(n-1)"),
  ("If a, b, c are in AP then b = (a + c)/2, and b is called the arithmetic mean of a and c.","arithmetic mean"),
  ("Pick the formula that matches what is given: use S = n/2 (a + l) when the last term is known.","choose formula")],
 ("How many terms of 24, 21, 18 ... must be taken so that the sum is 78?",[("a = 24, d = -3. S = n/2 (48 + (n - 1)(-3)) = 78.","Use the S formula."),("n(51 - 3n) = 156 gives 3n^2 - 51n + 156 = 0, i.e. n^2 - 17n + 52 = 0.","Simplify."),("(n - 4)(n - 13) = 0. Both n = 4 and 13 are valid: the terms after the 8th cancel out.","Both give the sum 78.")]),
 ("How do you find the sum of an AP?",["S = n/2 [2a + (n-1)d]","S = n/2 (a + l)","Choose formula by given data"],["Using n instead of n/2"]),
 ["S_n = n/2 [2a + (n - 1)d] and S_n = n/2 (a + l).","a_n = S_n - S_(n-1).","Arithmetic mean of a and c is (a + c)/2."],
 [num("r1-sn1",1,"Sum of the first 10 natural numbers",55,"10 x 11/2 = 55.",[(10,"Use the formula.")]),
  mcq("r1-sn2",1,"S_n for an AP with a, l and n terms is","n/2 (a + l)",[("n (a + l)","n/2 is needed."),("(a + l)/n","Not the sum.")],"Pair the first and last."),
  num("r2-sn3",2,"Sum of the first 20 terms of 5, 9, 13 ...",860,"S = 10 (10 + 19 x 4) = 10 x 86 = 860.",[(480,"Check the arithmetic.")]),
  mcq("r2-sn4",2,"Sum of first 5 odd numbers","25",[("15","1 + 3 + 5 + 7 + 9 = 25."),("30","Too big.")],"n squared = 25."),
  mcq("r2-sn5",2,"Assertion (A): S_n = n^2 for first n odd numbers. Reason (R): a = 1 and d = 2.","Both A and R are true and R explains A",[("A true, R false","R is correct."),("A false, R true","Substitute: n/2 (2 + 2n - 2) = n^2.")],"n/2 (2 + 2(n - 1)) = n^2."),
  num("r3-sn6",3,"a_n = 3 + 2n. Find a_1",5,"3 + 2 = 5.",[(3,"Put n = 1.")]),
  tf("r3-sn7",3,"If S_n = n^2 then a_n = 2n - 1.",True,"S_n - S_(n-1) = n^2 - (n-1)^2 = 2n - 1."),
  num("r3-sn8",3,"Arithmetic mean of 12 and 20",16,"(12 + 20)/2.",[(32,"Divide by 2.")])])
